import type { ComponentDefinition, ComponentMetadata, ComponentPinDefinition, ComponentPropertyDefinition, PinDirection, PinSide, PinSignal } from "./catalog.ts";
import { expandHorizontalHeader } from "./header-spacing.ts";

type Family = "breadboard" | "sensor" | "i2c-sensor" | "pixel" | "display" | "driver" | "actuator" | "switch" | "passive" | "logic" | "power" | "input";
type PartSpec = {
  id: string; name: string; manufacturer: string; variant: string; category: ComponentDefinition["category"];
  description: string; pins: string; source: string; section: string; family: Family;
  supplies?: ComponentMetadata["supplies"]; grounds?: string[]; interfaces?: string[]; aliases?: string[];
  controls?: Readonly<Record<string, ComponentPropertyDefinition>>; behavior: string; limitations?: string; libraryNote?: string;
  libraries?: ComponentMetadata["libraries"]; config?: Readonly<Record<string, string | number | boolean>>;
};
const n = (label: string, value: number, min: number, max: number, unit?: string): ComponentPropertyDefinition => ({ kind: "number", label, defaultValue: value, min, max, unit });
const b = (label: string, value = false): ComponentPropertyDefinition => ({ kind: "boolean", label, defaultValue: value });
const supply = (pins: string[], minVolts: number, maxVolts: number) => ({ pins, minVolts, maxVolts });
const library = (name: string, url: string, header: string, note: string) => ({ name, url, headers: [header], note });
const pinDirections: Record<string, PinDirection> = { i: "input", o: "output", b: "bidirectional", p: "power", g: "power", x: "passive", n: "passive" };
const pinSignals = (role: string, signal?: string): PinSignal[] => [role === "g" ? "ground" : role === "p" ? "power" : (signal ?? "digital") as PinSignal];

function pinList(text: string): ComponentPinDefinition[] {
  const names = text.split(/\s+/).filter(Boolean).map(token => token.split("/")[0]!);
  const half = Math.ceil(names.length / 2);
  return text.split(/\s+/).filter(Boolean).map((token, index) => {
    const [name, role = "i", signal] = token.split("/");
    return { id: names.filter(value => value === name).length > 1 ? `${name}_${index + 1}` : name!, label: name!, number: String(index + 1), direction: pinDirections[role!]!, signals: pinSignals(role!, signal), side: index < half ? "left" : "right", order: index < half ? index : names.length - index - 1, noConnect: role === "n" };
  });
}

type SvgPinPoint = { x: number; y: number; side: PinSide };
type SvgBounds = { left: number; top: number; right: number; bottom: number };
const DEFAULT_MODULE_BOUNDS: SvgBounds = { left: 24, top: 24, right: 196, bottom: 126 };

