function svgToComponentPoint(x: number, y: number, width: number, height: number, viewBoxHeight = 150) {
  const scale = Math.min(width / 220, height / viewBoxHeight);
  return {
    x: (width - 220 * scale) / 2 + x * scale,
    y: (height - viewBoxHeight * scale) / 2 + y * scale,
  };
}

function fixedSide(points: readonly { x: number; y: number }[], side: PinSide): SvgPinPoint[] {
  return points.map(point => ({ ...point, side }));
}

function headerPoints(x: number, y: number, count: number, side: PinSide = "bottom", spacing = 10): SvgPinPoint[] {
  return Array.from({ length: count }, (_, index) => ({ x: x + index * spacing, y, side }));
}

function screenshotPinPoints(type: string, pins: readonly ComponentPinDefinition[]): SvgPinPoint[] | undefined {
  const count = pins.length;
  const bottomHeaders: Readonly<Record<string, { x: number; y: number; spacing?: number }>> = {
    "neopixel-ring-24": { x: 50, y: 131 },
    "ws2812b-matrix-8x8": { x: 66, y: 142 },
    "electrolytic-capacitor-100uf": { x: 100, y: 136, spacing: 20 },
    dht11: { x: 83, y: 140, spacing: 18 },
    "bme280-gy-bme-p280": { x: 48, y: 132 },
    "sgp40-voc-sensor": { x: 48, y: 132 },
    "bme680-gas-sensor": { x: 48, y: 132 },
    "scd41-co2-sensor": { x: 48, y: 132 },
    "mpu-6050-breakout": { x: 48, y: 132 },
    "veml7700-light-sensor": { x: 48, y: 132 },
    "apds-9960-proximity-gesture": { x: 48, y: 132 },
    "hc-sr501": { x: 55, y: 109 },
    "mq-2-gas-sensor": { x: 64, y: 111 },
    "ld2410c-mmwave-radar": { x: 43, y: 129 },
    "rcwl-0516-microwave-radar": { x: 55, y: 134 },
    "vl53l0x-tof-distance": { x: 61, y: 108 },
    "as5600-magnetic-encoder": { x: 48, y: 132 },
    "vs1838b-ir-receiver-module": { x: 82, y: 121 },
    "tm1637-4-digit-display": { x: 80, y: 124 },
    "sh1107-oled-128x128": { x: 95, y: 137 },
    "st7735s-tft-1-8": { x: 70, y: 142 },
    "ili9341-tft-2-8": { x: 65, y: 142 },
    "epaper-2-9-spi": { x: 70, y: 142 },
    "gc9a01-round-tft": { x: 70, y: 142 },
    "max7219-8x8-matrix": { x: 51, y: 126, spacing: 17 },
    "ky-023-joystick": { x: 70, y: 137 },
    "stepper-28byj-48": { x: 72, y: 132, spacing: 16 },
    "nema17-stepper-17hs4401s": { x: 80, y: 140, spacing: 18 },
    "photoresistor-gl5528": { x: 94, y: 134, spacing: 32 },
    "tsop4838-ir-receiver": { x: 88, y: 132, spacing: 22 },
    "2n2222-transistor": { x: 78, y: 134, spacing: 32 },
    "pnp-transistor-2n3906": { x: 78, y: 134, spacing: 32 },
    "n-mosfet-2n7000": { x: 78, y: 134, spacing: 32 },
  };
  const header = bottomHeaders[type];
  if (header) {
    const layout = expandHorizontalHeader(header.x, count, header.spacing ?? 10);
    return headerPoints(layout.x, header.y, count, "bottom", layout.spacing);
  }

  if (type === "ws2812b-strip-30" || type === "ws2812b-strip-60") {
    return [
      { x: 16, y: 64, side: "left" }, { x: 16, y: 88, side: "left" },
      { x: 204, y: 64, side: "right" }, { x: 204, y: 88, side: "right" },
    ];
  }
  if (type === "capacitor-1uf") return [{ x: 48, y: 76, side: "left" }, { x: 172, y: 76, side: "right" }];
  if (type === "diode-1n4007") return [{ x: 29, y: 75, side: "left" }, { x: 195, y: 75, side: "right" }];
  if (type === "ntc-thermistor-10k") return [{ x: 81, y: 97, side: "left" }, { x: 139, y: 97, side: "right" }];
  if (type === "ds18b20-waterproof") return fixedSide([{ x: 25, y: 70 }, { x: 25, y: 78 }, { x: 25, y: 86 }], "left");
  if (type === "jsn-sr04t-ultrasonic") return fixedSide(Array.from({ length: count }, (_, index) => ({ x: 32, y: 51 + index * 8 })), "left");
  if (type === "mg996r-servo" || type === "sg90-servo") return fixedSide([{ x: 191, y: 54 }, { x: 191, y: 66 }, { x: 191, y: 78 }], "right");
  if (type === "r385-water-pump") return fixedSide([{ x: 24, y: 63 }, { x: 24, y: 79 }], "left");
  if (type === "solenoid-valve-12v") return fixedSide([{ x: 93, y: 20 }, { x: 129, y: 20 }], "top");
  if (type === "yf-s201-water-flow-sensor") return fixedSide([{ x: 90, y: 23 }, { x: 110, y: 23 }, { x: 130, y: 23 }], "top");
  if (type === "battery-9v") return fixedSide([{ x: 92, y: 15 }, { x: 128, y: 15 }], "top");
  if (type === "ne555-timer") return [
    ...Array.from({ length: 4 }, (_, index) => ({ x: 71.5 + index * 27, y: 10, side: "top" as const })),
    ...Array.from({ length: 4 }, (_, index) => ({ x: 71.5 + index * 27, y: 138, side: "bottom" as const })),
  ];
  if (type === "dip-switch-8") return Array.from({ length: 8 }, (_, index) => [
    { x: 41 + index * 18, y: 28, side: "top" as const },
    { x: 41 + index * 18, y: 119, side: "bottom" as const },
  ]).flat();
  if (type === "ir-remote-controller") return fixedSide([{ x: 94, y: 148 }, { x: 126, y: 148 }], "bottom");
  if (type === "tmc2209-stepper-driver") return pins.map(pin => ({ x: pin.side === "left" ? 57 : 163, y: 24 + pin.order * 8, side: pin.side }));

  return undefined;
}

function pinAnchors(type: string, pins: readonly ComponentPinDefinition[], width: number, height: number): ComponentPinDefinition[] {
  const viewBoxHeight = type === "breadboard-half" ? 260 : type === "breadboard-full" ? 430 : 150;
  const explicit = screenshotPinPoints(type, pins);
  if (explicit) return pins.map((pin, index) => {
    const point = explicit[index];
    return { ...pin, side: point?.side ?? pin.side, order: point?.side === "bottom" || point?.side === "top" ? index : pin.order, anchor: point ? svgToComponentPoint(point.x, point.y, width, height, viewBoxHeight) : undefined };
  });

  const bounds = PIN_BOUNDS_BY_TYPE[type] ?? DEFAULT_MODULE_BOUNDS;
  const sideCounts = new Map<PinSide, number>();
  for (const pin of pins) sideCounts.set(pin.side, (sideCounts.get(pin.side) ?? 0) + 1);
  const sideIndices = new Map<PinSide, number>();
  return pins.map(pin => {
    const count = sideCounts.get(pin.side) ?? 1;
    const index = sideIndices.get(pin.side) ?? 0;
    sideIndices.set(pin.side, index + 1);
    const fraction = (index + 1) / (count + 1);
    const point = pin.side === "left" ? { x: bounds.left, y: bounds.top + (bounds.bottom - bounds.top) * fraction }
      : pin.side === "right" ? { x: bounds.right, y: bounds.top + (bounds.bottom - bounds.top) * fraction }
        : pin.side === "top" ? { x: bounds.left + (bounds.right - bounds.left) * fraction, y: bounds.top }
          : { x: bounds.left + (bounds.right - bounds.left) * fraction, y: bounds.bottom };
    return { ...pin, anchor: svgToComponentPoint(point.x, point.y, width, height, viewBoxHeight) };
  });
}

function part(spec: PartSpec): ComponentDefinition {
  const width = spec.family === "breadboard" ? 344 : 236;
  const height = spec.family === "breadboard" ? (spec.id === "breadboard-full" ? 570 : 340) : Math.max(148, Math.ceil(pinList(spec.pins).length / 2) * 27 + 38);
  const pins = pinAnchors(spec.id, pinList(spec.pins), width, height);
  const properties = spec.controls ?? {};
  const metadata: ComponentMetadata = {
    manufacturer: spec.manufacturer, variant: spec.variant, kind: spec.family === "sensor" || spec.family === "i2c-sensor" ? "sensor" : "module",
    aliases: spec.aliases ?? [], interfaces: spec.interfaces ?? [], supplies: spec.supplies ?? [], groundPins: spec.grounds ?? [],
    documentation: [{ title: `${spec.name} variant reference`, url: spec.source, section: spec.section }],
    libraries: spec.libraries ?? [], libraryNote: spec.libraryNote ?? "The documented sketch subset uses core GPIO, ADC, Wire, SPI, or Servo calls only; undocumented library calls are not claimed.",
    notes: ["Simulation uses functional state and normalized logic levels, not waveform-level analog analysis or SPICE.", ...(spec.limitations ? [spec.limitations] : [])], verifiedOn: "2026-10-13",
  };
  return {
    id: spec.id, displayName: spec.name, category: spec.category, description: spec.description,
    width, height,
    accent: spec.category === "power" ? "#e8ad53" : spec.category === "sensors" ? "#21b8c2" : "#43cfb5", simulated: true, pins, properties,
    defaultProperties: Object.fromEntries(Object.entries(properties).map(([key, value]) => [key, value.defaultValue])), symbol: "module", metadata,
    simulation: { capability: "simulated", model: spec.id === "battery-9v" ? "battery-9v-runtime" : `screenshot-${spec.id}-runtime`, behavior: spec.behavior, limitations: spec.limitations ?? "Functional time-stepped device behavior; no waveform-level analog analysis, thermal model, radio propagation, optics, or mechanical forces." },
    requestAliases: spec.aliases,
  };
}

