const railPins = (rows: number) => {
  const half = Math.ceil(rows / 2);
  return [`L+_1-${half}`, `L-_1-${half}`, `R+_1-${half}`, `R-_1-${half}`, ...(rows > half ? [`L+_${half + 1}-${rows}`, `L-_${half + 1}-${rows}`, `R+_${half + 1}-${rows}`, `R-_${half + 1}-${rows}`] : [])];
};
function breadboard(id: "breadboard-half" | "breadboard-full", name: string, rows: number, source: string): ComponentDefinition {
  const groupPins: ComponentPinDefinition[] = [];
  const width = 344;
  const height = id === "breadboard-full" ? 570 : 340;
  const viewBoxHeight = id === "breadboard-full" ? 430 : 260;
  const bottom = id === "breadboard-full" ? 422 : 252;
  const rowY = (row: number) => 44 + (row - 1) * ((bottom - 88) / (rows - 1));
  for (let row = 1; row <= rows; row++) {
    groupPins.push({ id: `A${row}-E${row}`, label: `A${row}–E${row}`, number: `A${row}–E${row}`, direction: "passive", signals: ["digital", "analog", "power", "ground"], side: "left", order: row - 1, anchor: svgToComponentPoint(39, rowY(row), width, height, viewBoxHeight) });
    groupPins.push({ id: `F${row}-J${row}`, label: `F${row}–J${row}`, number: `F${row}–J${row}`, direction: "passive", signals: ["digital", "analog", "power", "ground"], side: "right", order: row - 1, anchor: svgToComponentPoint(185, rowY(row), width, height, viewBoxHeight) });
  }
  const rails = railPins(rows);
  rails.forEach((pin, index) => {
    const match = /^(L|R)[+-]_(\d+)-/.exec(pin);
    const side = match?.[1] === "R" ? "right" : "left";
    const railY = Number(match?.[2]) === 1 ? 23 : bottom - 19;
    groupPins.push({ id: pin, label: pin.replaceAll("_", " "), number: pin, direction: "passive", signals: ["power", "ground"], side, order: index, anchor: svgToComponentPoint(side === "left" ? 31 : 189, railY, width, height, viewBoxHeight) });
  });
  const sizeAliases = id === "breadboard-half"
    ? ["half-size breadboard", "half size breadboard", "half breadboard", "BB400"]
    : ["full-size breadboard", "full size breadboard", "full breadboard", "BB830"];
  return { id, displayName: name, category: "passives", description: `${rows}-row solderless board. Each A–E and F–J row group is one electrically connected endpoint; power rails are continuous only within their labeled segment.`, width: 344, height: id === "breadboard-full" ? 570 : 340, accent: "#c6c6bc", simulated: true, symbol: "module", pins: groupPins, properties: {}, defaultProperties: {}, metadata: { manufacturer: "BusBoard Prototype Systems", variant: id === "breadboard-half" ? "BB400-compatible 400 tie-point half-size board, split power rails" : "BB830-compatible 830 tie-point full-size board, split power rails", kind: "module", aliases: ["solderless breadboard", "protoboard", "breadboard rows", `${rows} row`, ...sizeAliases], interfaces: ["Solderless row groups", "Split power rails"], supplies: [], groundPins: [], documentation: [{ title: `${name} row/rail electrical layout`, url: source, section: "Terminal strips A–E and F–J; split positive and negative power rails" }], libraries: [], libraryNote: "No code library is needed. Wire directly to the endpoint representing each internally connected breadboard group.", notes: ["Each row-group endpoint collapses the five holes into one connected net; the center trench isolates the two groups.", "Power-rail endpoints are split into labeled top/bottom segments; users must add wires between sections if desired."], verifiedOn: "2026-10-13" }, simulation: { capability: "simulated", model: `screenshot-${id}-runtime`, behavior: "Each terminal endpoint represents exactly one connected hole group or rail segment; separate groups remain electrically isolated.", limitations: "The board's contact resistance, spring wear, parasitic capacitance, and physical hole spacing are not modeled." } };
}

